import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';

const Login = () => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    try {
      const response = await axios.post('http://localhost:4000/login', {
        username,
        password,
      });

      // Save token to localStorage or sessionStorage
      localStorage.setItem('authToken', response.data.token);

      // Redirect to main page
      navigate('/');
    } catch (err) {
      setError(err.response?.data?.error || 'Login failed. Please try again.');
    }
  };

  return (
    <div style={{ width: '300px', margin: '50px auto', textAlign: 'center' }}>
      <h2>Login</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <input
            type="text"
            placeholder="Enter your username" // Placeholder for the username field
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            required
            style={{ width: '100%', padding: '8px', marginBottom: '10px' }}
          />
        </div>
        <div>
          <input
            type="password"
            placeholder="Enter your password" // Placeholder for the password field
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            style={{ width: '100%', padding: '8px', marginBottom: '10px' }}
          />
        </div>
        <button
          type="submit"
          style={{
            width: '100%',
            padding: '10px',
            backgroundColor: '#007BFF',
            color: '#fff',
            border: 'none',
            cursor: 'pointer',
          }}
        >
          Login
        </button>
        {error && <p style={{ color: 'red', marginTop: '10px' }}>{error}</p>}
      </form>
    </div>
  );
};

// Middleware
app.use(bodyParser.urlencoded({ extended: true }));
app.use(express.json());
app.set('view engine', 'ejs');

// Serve login page
app.get('/', (req, res) => {
  res.render('login', { error: null });
});

// Handle login submission
app.post('/login', (req, res) => {
  const { username, password } = req.body;

  // Example validation (replace with actual logic)
  if (username === 'admin' && password === 'password') {
    // Redirect to the frontend page after successful login
    return res.redirect('http://localhost:3000/');
  }

  // Reload login page with an error message
  res.render('login', { error: 'Invalid username or password' });
});

// Start the server
app.listen(port, () => {
  console.log(`Login service running on http://localhost:${port}`);
});
export default Login;
